// Finds leads whose response clock has passed an SLA level, counting business minutes only.
//   level "rep"     → 60 business minutes without contact → remind the owner
//   level "manager" → 240 business minutes without contact → escalate to the sales manager
// Business hours: Mon–Fri 09:00–18:00 America/New_York, minus holidays. A lead sent Friday 17:30
// is 30 minutes old at Monday 09:00, not 63 hours.
const TZ = 'America/New_York';
const OPEN_MIN = 9 * 60;
const CLOSE_MIN = 18 * 60;
const WORKDAYS = [1, 2, 3, 4, 5];
const HOLIDAYS = ['2026-11-26', '2026-12-25', '2027-01-01', '2027-01-18', '2027-05-31', '2027-07-05'];
const LEVELS = [{ level: 'rep', after: 60 }, { level: 'manager', after: 240 }];
const LOOKBACK_DAYS = 5;
const RANK = { '': 0, rep: 1, manager: 2, met: 3 };

const fmt = new Intl.DateTimeFormat('en-US', {
  timeZone: TZ, hour12: false, weekday: 'short', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit',
});
const local = (ms) => {
  const p = Object.fromEntries(fmt.formatToParts(new Date(ms)).map((x) => [x.type, x.value]));
  return {
    day: `${p.year}-${p.month}-${p.day}`,
    dow: ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].indexOf(p.weekday),
    min: (Number(p.hour) % 24) * 60 + Number(p.minute),
  };
};
// Walks the interval in 5-minute steps. Uses real instants, so DST changes are handled by Intl.
const businessMinutes = (fromMs, toMs) => {
  const STEP = 5;
  let total = 0;
  for (let t = fromMs; t < toMs; t += STEP * 60000) {
    const l = local(t);
    if (WORKDAYS.includes(l.dow) && !HOLIDAYS.includes(l.day) && l.min >= OPEN_MIN && l.min < CLOSE_MIN) {
      total += Math.min(STEP, (toMs - t) / 60000);
    }
  }
  return Math.round(total);
};

const now = Date.now();
const candidates = [];
for (const { json: row } of $input.all()) {
  const submitted = Date.parse(row.last_submitted_at);
  if (!row.email || !row.hubspot_contact_id || !Number.isFinite(submitted)) continue;
  if (now - submitted > LOOKBACK_DAYS * 86400000) continue;
  const current = String(row.sla_level || '').toLowerCase();
  if (current === 'met' || current === 'manager') continue;

  const elapsed = businessMinutes(submitted, now);
  const due = [...LEVELS].reverse().find((l) => elapsed >= l.after);
  if (!due || RANK[due.level] <= RANK[current]) continue;
  candidates.push({
    email: row.email,
    name: [row.first_name, row.last_name].filter(Boolean).join(' '),
    company: row.company || '',
    hubspot_contact_id: String(row.hubspot_contact_id),
    submitted_at: row.last_submitted_at,
    business_minutes: elapsed,
    due_level: due.level,
  });
}

if (!candidates.length) return [];
const batch = candidates.slice(0, 100); // HubSpot batch read limit
return [{
  json: {
    candidates: batch,
    request_body: {
      properties: ['hubspot_owner_id', 'hs_lead_status', 'notes_last_contacted', 'hs_last_sales_activity_timestamp', 'lifecyclestage'],
      inputs: batch.map((c) => ({ id: c.hubspot_contact_id })),
    },
  },
}];

// Checks HubSpot before alerting anyone: the sheet can be out of date, the CRM is the truth.
// A lead counts as contacted if, after it was submitted, the rep logged a call/email/meeting
// (hs_last_sales_activity_timestamp, notes_last_contacted) or moved the lead status past NEW/OPEN.
// Output: one item per lead with the new sla_level, plus who should be told.
const MANAGER_EMAIL = 'sales@example.com';
const candidates = $('Find SLA Candidates').first().json.candidates;
const crm = Object.fromEntries(($('HubSpot · Batch Read Contacts').first().json.results || []).map((r) => [String(r.id), r.properties || {}]));
// owner id → rep. An inactive rep (left the company, but still owns contacts in HubSpot) must not receive
// reminders nobody will read: their leads go to the manager. Seen live on 2026-10-18.
const isActive = (r) => ['true', 'yes', '1', 'y', 'x'].includes(String(r.active).trim().toLowerCase());
const reps = {};
for (const r of $input.all().map((i) => i.json).filter((x) => x.hubspot_owner_id)) {
  const id = String(r.hubspot_owner_id);
  if (!reps[id] || (!isActive(reps[id]) && isActive(r))) reps[id] = r; // prefer an active row for the same id
}
const UNTOUCHED = ['', 'NEW', 'OPEN'];

const now = new Date().toISOString();
return candidates.map((c) => {
  const p = crm[c.hubspot_contact_id];
  const submitted = Date.parse(c.submitted_at);
  const after = (v) => v && Date.parse(v) > submitted;
  const contacted = p && (after(p.hs_last_sales_activity_timestamp) || after(p.notes_last_contacted) || !UNTOUCHED.includes(String(p.hs_lead_status || '').toUpperCase()));

  if (contacted) return { json: { ...c, sla_level: 'met', sla_alerted_at: now, notify: false } };

  const rep = p && reps[String(p.hubspot_owner_id || '')];
  const owner = rep && isActive(rep) ? rep : null;
  // No owner, owner not in the reps sheet, or owner inactive: nobody will act on a "rep" reminder, so go to the manager.
  const level = !owner ? 'manager' : c.due_level;
  const recipient = level === 'rep' ? owner.email : MANAGER_EMAIL;
  return {
    json: {
      ...c,
      sla_level: level,
      sla_alerted_at: now,
      notify: true,
      recipient,
      owner_name: owner ? owner.name : rep ? `${rep.name} (inactive)` : '(no owner)',
      missing_from_crm: !p,
    },
  };
});

// One email per recipient listing all of their overdue leads, instead of one email per lead.
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fmtAge = (m) => (m >= 60 ? `${Math.floor(m / 60)} h ${m % 60} min` : `${m} min`);

const groups = {};
for (const { json: l } of $input.all()) {
  if (!l.notify) continue;
  (groups[l.recipient] ||= []).push(l);
}

return Object.entries(groups).map(([to, leads]) => {
  const isManager = leads.some((l) => l.sla_level === 'manager');
  leads.sort((a, b) => b.business_minutes - a.business_minutes);
  const rows = leads.map((l) => `<tr><td>${esc(l.name || l.email)}</td><td>${esc(l.company)}</td><td>${esc(l.email)}</td>`
    + `<td>${esc(l.owner_name)}</td><td style="text-align:right">${fmtAge(l.business_minutes)}</td></tr>`).join('');
  const intro = isManager
    ? 'These leads have waited more than 4 business hours without any logged contact.'
    : 'These leads are yours and have waited more than 1 business hour. Please call or email them, then log it in HubSpot.';
  return {
    json: {
      email_to: to,
      email_subject: `${isManager ? '🚨 SLA breach' : '⏰ Reminder'}: ${leads.length} lead${leads.length > 1 ? 's' : ''} waiting`,
      email_html: `<p>${intro}</p><table cellpadding="6" style="border-collapse:collapse;font-family:Arial;font-size:13px" border="1">`
        + '<tr style="background:#f3f4f6"><th>Lead</th><th>Company</th><th>Email</th><th>Owner</th><th>Waiting (business time)</th></tr>'
        + `${rows}</table><p style="color:#666">Business hours: Mon–Fri 9:00–18:00 ET.</p>`,
    },
  };
});
